<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Detail Pesanan</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h4 mb-3"><?php echo html_escape($order->order_number); ?></h1><div class="card border-0 shadow-sm"><div class="card-body"><div>Status pesanan: <strong><?php echo html_escape($order->status); ?></strong></div><?php if ($shipment): ?><div class="mt-2">Status pengiriman: <strong><?php echo html_escape($shipment->status); ?></strong></div><?php endif; ?><table class="table mt-3"><thead><tr><th>Produk</th><th>Jumlah</th><th>Total</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?php echo html_escape($item->name); ?></td><td><?php echo number_format((float)$item->quantity,3,',','.'); ?></td><td>Rp <?php echo number_format((float)$item->total,0,',','.'); ?></td></tr><?php endforeach; ?></tbody></table><div class="text-end fs-5 fw-bold">Rp <?php echo number_format((float)$order->total,0,',','.'); ?></div></div></div></main></body></html>
